.spa502-promos{background:var(--spa-purple);padding:112px 0;color:#fff;position:relative;overflow:hidden}.spa502-promos:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 14% 20%,rgba(255,255,255,.18) 0 50px,transparent 51px),radial-gradient(circle at 37% 34%,rgba(255,255,255,.18) 0 90px,transparent 91px),radial-gradient(circle at 43% 18%,transparent 0 56px,rgba(255,255,255,.18) 57px 66px,transparent 67px);opacity:.75}.spa502-promos .spa502-container{position:relative}.spa502-promos .spa502-title{color:#fff}.spa502-promos .spa502-title h2,.spa502-promos .spa502-title p,.spa502-promos .spa502-lotus{color:#fff}.spa502-promos .spa502-lotus i,.spa502-promos .spa502-lotus i:before,.spa502-promos .spa502-lotus i:after{background:#fff}.spa502-promo-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:28px}.spa502-promo-grid a{display:block;border:10px solid #fff;border-radius:6px;overflow:hidden;background:#fff;box-shadow:0 10px 28px rgba(0,0,0,.08)}.spa502-promo-grid img{width:100%;aspect-ratio:1;object-fit:cover;display:block}
.spa502-products{background:#fff}.spa502-product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:42px 28px}.spa502-product-card{text-align:center;color:var(--spa-ink);text-decoration:none}.spa502-product-image{position:relative;border:1px solid var(--spa-line);border-radius:8px;background:#fff;padding:18px;min-height:335px;display:grid;place-items:center}.spa502-product-image img{max-width:100%;max-height:295px;object-fit:contain}.spa502-heart{position:absolute;right:18px;top:16px;color:var(--spa-purple);font-size:24px}.spa502-sale{position:absolute;left:14px;top:12px;background:var(--spa-pink);color:#fff;padding:8px 18px;font-weight:900;clip-path:polygon(0 0,100% 0,86% 100%,0 100%)}.spa502-tags{position:absolute;left:14px;bottom:12px;display:flex;gap:6px}.spa502-tag{display:inline-flex;align-items:center;gap:5px;border-radius:4px;background:#ed001f;color:#fff;padding:8px 12px;font-weight:900;font-size:17px}.spa502-tag.is-hot{background:#ffc10a}.spa502-product-card h3{margin:20px 0 10px;font-size:22px;line-height:1.3;min-height:58px}.spa502-price{display:block;color:var(--spa-purple);font-size:20px;font-weight:900}.spa502-price del{margin-left:8px;color:#777}.spa502-stars{display:block;margin-top:10px;color:var(--spa-gold);letter-spacing:2px}
.spa502-deals{position:relative;background:var(--spa-purple);color:#fff;padding:98px 0;overflow:hidden}.spa502-deals:before{content:"";position:absolute;inset:0;background:linear-gradient(rgba(113,69,138,.72),rgba(113,69,138,.72)),var(--deal-bg) center/cover}.spa502-deals__grid{position:relative;display:grid;grid-template-columns:.85fr 1.45fr;gap:50px;align-items:center}.spa502-deal-copy{text-align:center}.spa502-deal-copy h2{margin:18px 0;font-size:42px}.spa502-deal-copy p{font-family:Playball,cursive;font-size:29px;margin:0 0 20px}.spa502-deal-copy span{font-size:20px;text-transform:uppercase}.spa502-deal-rail{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.spa502-deal-rail .spa502-product-card{background:#fff;padding:14px;text-align:left}.spa502-deal-rail .spa502-product-image{border:0;border-radius:0;min-height:230px;padding:8px}.spa502-deal-rail .spa502-product-card h3{font-size:20px;min-height:62px}.spa502-progress{height:12px;border-radius:999px;background:#d9c6df;overflow:hidden;margin-top:14px}.spa502-progress i{display:block;width:45%;height:100%;border-radius:999px;background:var(--spa-purple)}
.spa502-intro{background:#fff}.spa502-intro__grid{display:grid;grid-template-columns:1fr .9fr 1fr;align-items:center;gap:42px}.spa502-intro__copy{text-align:center;color:var(--spa-muted);font-size:20px;line-height:1.65}.spa502-intro__copy h3{font-family:Playball,cursive;color:var(--spa-purple);font-size:30px;font-weight:400}.spa502-intro__copy h3:after{content:"";display:block;height:3px;background:var(--spa-purple);margin:12px 0 28px}.spa502-intro__image img{width:100%;object-fit:contain}.spa502-benefits{display:grid;gap:22px;color:var(--spa-muted);font-size:20px}.spa502-benefits span{display:grid;grid-template-columns:28px 1fr;gap:12px;align-items:start}.spa502-benefits i{color:var(--spa-purple);margin-top:3px}
.spa502-posts{background:var(--spa-purple);padding:96px 0;color:#fff;position:relative;overflow:hidden}.spa502-posts:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 43% 15%,rgba(255,255,255,.2) 0 110px,transparent 112px),radial-gradient(circle at 37% 34%,transparent 0 62px,rgba(255,255,255,.18) 63px 73px,transparent 74px)}.spa502-posts .spa502-container{position:relative}.spa502-posts .spa502-title,.spa502-posts .spa502-title h2,.spa502-posts .spa502-title p,.spa502-posts .spa502-lotus{color:#fff}.spa502-posts .spa502-lotus i,.spa502-posts .spa502-lotus i:before,.spa502-posts .spa502-lotus i:after{background:#fff}.spa502-post-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:28px}.spa502-post-card{display:block;background:#fff;color:var(--spa-muted);text-decoration:none;border-radius:5px;overflow:hidden}.spa502-post-card__media{position:relative}.spa502-post-card img{width:100%;aspect-ratio:1.34;object-fit:cover;display:block}.spa502-post-card time{position:absolute;left:22px;bottom:16px;display:inline-flex;align-items:center;gap:10px;background:#fff;color:var(--spa-purple);font-weight:900;padding:10px 14px;box-shadow:0 5px 14px rgba(0,0,0,.16)}.spa502-post-card time i{background:var(--spa-purple);color:#fff;margin:-10px 0 -10px -14px;padding:12px}.spa502-post-card__body{padding:24px 22px 28px}.spa502-post-card h3{margin:0 0 18px;color:var(--spa-purple);font-size:22px;line-height:1.35;text-transform:uppercase}.spa502-post-card p{margin:0;font-size:18px;line-height:1.65}
.spa502-partners{padding:70px 0;background:#fff}.spa502-partners__rail{display:grid;grid-auto-flow:column;grid-auto-columns:180px;justify-content:space-between;gap:42px;overflow-x:auto;align-items:center}.spa502-partners a{height:120px;display:grid;place-items:center;text-decoration:none;color:#9b7aaa}.spa502-partners img{max-width:170px;max-height:95px;object-fit:contain}.spa502-partners strong{font-size:26px;text-align:center;color:#8b6a99}
.spa502-newsletter{padding:88px 0;background:#fff}.spa502-title--center{margin-bottom:42px}.spa502-newsletter__form{width:min(820px,100%);margin:0 auto;display:grid;grid-template-columns:1fr 170px;box-shadow:0 15px 30px rgba(113,69,138,.18)}.spa502-newsletter__form input,.spa502-newsletter__form button{height:66px;border:0;font:800 20px Nunito,Arial,sans-serif}.spa502-newsletter__form input{padding:0 30px;background:#fff;color:var(--spa-ink)}.spa502-newsletter__form button{background:var(--spa-purple);color:#fff;text-transform:uppercase;cursor:pointer}.spa502-footer{background:var(--spa-purple);color:#fff}.spa502-footer__grid{display:grid;grid-template-columns:1.45fr .9fr 1.15fr;gap:90px;padding:100px 0 70px}.spa502-footer h3{margin:0;font-size:29px}.spa502-footer__rule{display:block;width:78px;height:5px;margin:20px 0 30px;background:linear-gradient(90deg,rgba(255,255,255,.58) 0 26%,transparent 26% 40%,#fff 40%)}.spa502-footer p,.spa502-footer li{font-size:21px;line-height:1.7}.spa502-footer p i{margin-right:18px}.spa502-footer a{color:#fff;text-decoration:none}.spa502-footer ul{list-style:none;padding:0;margin:0;display:grid;gap:16px}.spa502-footer__social{display:flex;gap:18px}.spa502-footer__social a{width:58px;height:58px;border:1px solid rgba(255,255,255,.75);border-radius:6px;display:grid;place-items:center;font-size:23px}.spa502-footer__payment-title{margin-top:48px!important}.spa502-payment{display:flex;flex-wrap:wrap;gap:8px}.spa502-payment span{background:#fff;color:#304;min-width:66px;padding:8px 10px;text-align:center;font-weight:900}.spa502-footer__bottom{border-top:1px solid rgba(255,255,255,.13);padding:26px 0;text-align:center}
.spa502-page-head{padding:70px 0 40px;background:#f8f5fa}.spa502-page-head h1{margin:0;font-size:clamp(34px,4vw,56px);color:var(--spa-purple)}.spa502-page-head p{margin:10px 0 0;color:var(--spa-muted);font-size:18px}.spa502-breadcrumb{display:flex;gap:8px;margin-bottom:14px;color:var(--spa-muted);font-weight:800}.spa502-breadcrumb a{color:var(--spa-purple);text-decoration:none}.spa502-subpage{padding:70px 0}.spa502-list-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:30px}.spa502-list-card{display:block;text-decoration:none;color:inherit}.spa502-list-card img{width:100%;aspect-ratio:1;object-fit:contain;border:1px solid var(--spa-line);border-radius:8px;padding:18px}.spa502-list-card h2{font-size:22px;color:var(--spa-ink)}.spa502-detail{display:grid;grid-template-columns:.9fr 1.1fr;gap:50px}.spa502-detail img{width:100%;border-radius:8px}.spa502-detail-body{font-size:18px;line-height:1.8;color:var(--spa-muted)}.spa502-form{display:grid;gap:16px}.spa502-form input,.spa502-form textarea{border:1px solid var(--spa-line);border-radius:8px;padding:15px;font:inherit}.spa502-form textarea{min-height:150px}.spa502-empty{padding:30px;border:1px dashed var(--spa-line);border-radius:8px;color:var(--spa-muted)}
.xd-editor,.xd-item-modal,.xd-auth-modal{font-family:Nunito,Arial,sans-serif}
@media(max-width:1120px){.spa502-navrow__inner{grid-template-columns:1fr auto}.spa502-menu-toggle{display:grid;place-items:center}.spa502-navigation{display:none;grid-column:1/-1;flex-direction:column;align-items:flex-start;padding:18px 0}.spa502-navigation.is-open{display:flex}.spa502-actions{justify-content:flex-end}.spa502-product-grid,.spa502-promo-grid,.spa502-post-grid,.spa502-deal-rail,.spa502-list-grid{grid-template-columns:repeat(2,1fr)}.spa502-deals__grid,.spa502-intro__grid,.spa502-footer__grid{grid-template-columns:1fr}.spa502-hero__copy{grid-template-columns:1fr}.spa502-hero__text{grid-column:1;background:rgba(255,255,255,.78);padding:36px;border-radius:10px}.spa502-category-rail{grid-auto-columns:240px}}
@media(max-width:720px){:root{--spa-container:calc(100% - 28px)}.spa502-topbar{height:auto}.spa502-topbar__inner{padding:10px 0;flex-wrap:wrap}.spa502-topbar__spacer{display:none}.spa502-divider{display:none}.spa502-navrow{height:auto}.spa502-navrow__inner{padding:16px 0}.spa502-brand strong{font-size:25px}.spa502-actions{gap:11px}.spa502-actions a,.spa502-actions button{font-size:22px}.spa502-hero__slide,.spa502-hero__copy{min-height:540px}.spa502-hero__nav{width:48px;height:48px}.spa502-section{padding:66px 0}.spa502-product-grid,.spa502-promo-grid,.spa502-post-grid,.spa502-deal-rail,.spa502-list-grid{grid-template-columns:1fr}.spa502-category__image{width:210px;height:210px}.spa502-newsletter__form{grid-template-columns:1fr}.spa502-detail{grid-template-columns:1fr}.spa502-footer__grid{gap:34px;padding:70px 0 48px}}
</style>
